  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    advantage_w = batch.get('advantage_w', ops.zeros_like(log_prob_w))\n    advantage_l = batch.get('advantage_l', ops.zeros_like(log_prob_l))\n    # Compute the difference in log probabilities\n    diff_log_prob = ops.sub(log_prob_w, log_prob_l)\n    # Compute the difference in advantage signals\n    diff_advantage = ops.sub(advantage_w, advantage_l)\n    # Calculate the preference score\n    score = ops.mul(diff_log_prob, diff_advantage)\n    # Apply logsigmoid to encourage preferred pairs\n    loss_vals = ops.logsigmoid(score)\n    # Return the mean loss over the batch\n    return ops.mean(loss_vals)"
}

