{
  "name": "pairwise_preference_advzscore_loss",
  "intuition": "Z-score normalize advantage_w and advantage_l with detached mean/std for stable scaling, then compute pairwise preference loss with logsigmoid difference and weighted mean.",
  "pseudocode": "eps=1e-8; mean_w=mean(advantage_w).detach(); std_w=sqrt(mean((advantage_w - mean_w)^2)).detach(); mean_l=mean(advantage_l).detach(); std_l=sqrt(mean((advantage_l - mean_l)^2)).detach(); z_w=(advantage_w - mean_w)/(std_w+eps); z_l=(advantage_l - mean_l)/(std_l+eps); diff=z_w - z_l; loss=-logsigmoid(diff)*weight; return mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_zscore",
    "signal_family": "advantage",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "none",
    "other_hparams": "eps=1e-8"
  },
  "operators_used": ["zscore", "logsigmoid", "mean", "sub", "mul", "neg", "add", "div", "sqrt"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    weight = batch['weight']\n    mean_w = ops.mean(advantage_w).detach()\n    var_w = ops.mean(ops.mul(ops.sub(advantage_w, mean_w), ops.sub(advantage_w, mean_w)))\n    std_w = ops.sqrt(ops.clamp(var_w, min=eps)).detach()\n    mean_l = ops.mean(advantage_l).detach()\n    var_l = ops.mean(ops.mul(ops.sub(advantage_l, mean_l), ops.sub(advantage_l, mean_l)))\n    std_l = ops.sqrt(ops.clamp(var_l, min=eps)).detach()\n    z_w = ops.div(ops.sub(advantage_w, mean_w), std_w + eps)\n    z_l = ops.div(ops.sub(advantage_l, mean_l), std_l + eps)\n    diff = ops.sub(z_w, z_l)\n    loss = ops.neg(ops.logsigmoid(diff))\n    loss = ops.mul(loss, weight)\n    return ops.mean(loss)\n"
}

{
  "name": "Weighted Pairwise Hinge-Style Advantage Margin Loss",
  "intuition": "Removed the logsigmoid to eliminate smooth but ambiguous gradient regions causing joint preference violation. Instead, implemented a hinge-like loss that enforces a positive margin for correctly ordered pairs. Specifically, computed diff = advantage_gap * (log_prob_w - log_prob_l) - margin, clamped at zero to penalize only incorrect or borderline orderings. This guarantees zero loss when the preferred item outperforms by at least the margin, and positive loss otherwise. The resultant piecewise linear formulation yields consistent nonzero gradient directions when needed and zero gradients for already satisfied preferences, fixing joint preference violations while respecting weighting.",
  "pseudocode": "margin = 0.5\ndiff = advantage_gap * (log_prob_w - log_prob_l) - margin\nloss = relu(-diff)  # hinge loss penalizes margin violations\nif weight exists:\n  loss *= weight\nreturn mean(loss)",
  "hyperparams": {
    "margin": 0.5
  },
  "operators_used": [
    "sub",
    "mul",
    "relu",
    "mean"
  ],
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_gap"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    adv_gap = batch['advantage_gap']\n    weight = batch.get('weight', None)\n    margin_tensor = ops.mul(ops.ones_like(adv_gap), 0.5)\n    diff_unthresholded = ops.sub(lpw, lpl)\n    diff = ops.sub(ops.mul(adv_gap, diff_unthresholded), margin_tensor)\n    loss = ops.relu(ops.neg(diff))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
}

