{
  "name": "pairwise_logsigmoid_advantage_gap_clipped_weighted_avg",
  "intuition": "Simplified the code to remove any syntax errors (no line continuation characters), ensured that only available keys are accessed from batch, and stabilized the margin by clamping the input to logsigmoid within [-20, 20]. This prevents numerical instability due to very large or small margins. Using advantage_gap prioritizes meaningful preference signal. Weight normalization by the sum of weights with epsilon added ensures stable scaling and training robustness.",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_gap"
    ],
    "returns": "scalar"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_gap = batch['advantage_gap']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    x = ops.add(ops.mul(alpha * scale, ops.sub(lpw, lpl)), ops.mul(beta, advantage_gap))\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = ops.neg(ops.logsigmoid(x))\n    weighted_loss = ops.mul(loss, weight)\n    denom = ops.add(ops.sum(weight), 1e-8)\n    normalized_loss = ops.div(ops.sum(weighted_loss), denom)\n    return normalized_loss"
}

